const NAMES = {"4624": "Successful logon", "4625": "Failed logon", "4672": "Special privileges assigned at logon", "4688": "Process created", "4719": "Audit policy changed", "4720": "User account created", "4722": "User account enabled", "4725": "User account disabled", "4726": "User account deleted", "4728": "Added to global security group", "4732": "Added to local security group (e.g., Administrators)", "4740": "Account locked out", "4756": "Added to universal security group", "1102": "Security log cleared", "104": "System log cleared", "7045": "New service installed", "7040": "Service start type changed", "6005": "Event log started (boot)", "6006": "Clean shutdown", "6008": "Unexpected shutdown", "1116": "Defender detected malware", "1117": "Defender took action", "5001": "Defender real-time protection disabled", "5007": "Defender configuration changed", "4104": "Suspicious PowerShell script block", "3008": "DNS query"};
const CRITICAL = ["1102", "104", "4719", "5001"];
const WATCH = ["4720", "4722", "4725", "4726", "4728", "4732", "4740", "4756", "5007", "7045", "1116", "1117"];
const toMap = res => Object.fromEntries((res || []).map(m => [`${m.metric.event_id || '?'}|${m.metric.channel || '?'}`, Number(m.value[1])]));
const c24 = toMap($('Counts 24h').first().json.data?.result);
const c7 = toMap($('Counts 7d').first().json.data?.result);
const event_counts = Object.entries(c24).sort((a, b) => b[1] - a[1]).map(([k, n]) => {
  const [event_id, channel] = k.split('|');
  const avg = (c7[k] || 0) / 7;
  return { event_id, channel, name: NAMES[event_id] || 'other', count_24h: n, avg_per_day_7d: Math.round(avg * 10) / 10, spike: n >= 5 && n > 2 * Math.max(avg, 1) };
});
const notable = [];
for (const s of ($('Notable Events').first().json.data?.result || [])) {
  for (const [ts, line] of s.values) {
    let e; try { e = JSON.parse(line); } catch (err) { e = { message: line }; }
    notable.push({ event_id: s.stream.event_id, name: NAMES[s.stream.event_id] || 'other', time: e.timeCreated || null, summary: String(e.message || '').slice(0, 200) });
  }
}
notable.sort((a, b) => String(b.time).localeCompare(String(a.time)));
const ids = new Set(event_counts.map(r => r.event_id));
const severity_floor = CRITICAL.some(i => ids.has(i)) ? 'investigate'
  : (WATCH.some(i => ids.has(i)) || event_counts.some(r => r.spike)) ? 'watch' : 'info';
return [{ json: { facts: { window: 'last 24h', event_counts, notable_events: notable.slice(0, 25) }, severity_floor } }];

const RANK = ['info', 'watch', 'investigate'];
const bf = $('Build Facts').first().json;
let d;
try { d = JSON.parse(String($input.first().json.text || '').replace(/```json|```/g, '').trim()); }
catch (e) { d = { headline: 'LLM summary unavailable - facts only', findings: [], recommended_checks: [], llm_error: true }; }
const llmSev = RANK.includes(d.severity) ? d.severity : 'info';
const severity = RANK[Math.max(RANK.indexOf(llmSev), RANK.indexOf(bf.severity_floor))]; // rules can raise, never lower
const digest = { date: $now.toISODate(), severity, severity_floor: bf.severity_floor, llm_severity: d.severity ?? null,
  headline: d.headline || '', findings: d.findings || [], recommended_checks: d.recommended_checks || [],
  event_counts: bf.facts.event_counts, source: 'n8n', note: 'AI-generated summary; verify against raw events' };
return [{ json: { digest, lokiBody: { streams: [{ stream: { job: 'ai_digest', source: 'n8n', severity },
  values: [[`${Date.now()}000000`, JSON.stringify(digest)]] }] } } }];
